    if dt < 0.02:
        dt = 0.02
    if dt > 1.0:
        dt = 1.0
    try:
        target = float(t_raw)
    except Exception:
        target = 0.6
    if not math.isfinite(target):
        target = 0.6
    if target < 0.0:
        target = 0.0
    if target > 0.85:
        target = 0.85
    try:
        y = float(y_raw)
