    U_MIN = 0.0
    U_MAX = 0.85
    ff = FF_DZ + target / FF_K
    if not math.isfinite(ff):
        ff = 0.52
    if ff < 0.15:
        ff = 0.15
    if ff > 0.75:
        ff = 0.75
    e = target - yf
    if e < -1.0:
        e = -1.0
    if e > 1.0:
        e = 1.0
    P = Kp * e
    integ = integ_prev
    if abs(e) < 0.20:
        integ = integ_prev + Ki * e * dt
        if integ < -I_MAX:
            integ = -I_MAX
        if integ > I_MAX:
            integ = I_MAX
    u_test = ff + P + integ
    if u_test > U_MAX and e > 0.0:
        integ = integ_prev
    if u_test < U_MIN and e < 0.0:
