    elif yf > 0.75:
        if u > 0.25:
            u = 0.25
        if integ > 0.0:
            integ = 0.0
    u = _clamp(u, U_MIN, 1.0)
    if not math.isfinite(u):
        u = ff
        u = _clamp(u, U_MIN, 1.0)
    new_state = {"yf": float(yf), "integ": float(integ)}
    return (float(u), new_state)
